 hit.velocity_m_s={0,0,.2};h={};auto approach=evaluate_moving_wall(sphere,hit,material,h,1e-6);near(approach.particle.force_a.z,18,1e-10,"wall normal speed enters damping");
 hit.velocity_m_s={0,.3,0};hit.omega_rad_s={0,0,1};h={};auto rotary=evaluate_moving_wall(sphere,hit,material,h,1e-6);near(rotary.wall.reaction_torque_nm.z,-.3*rotary.particle.force_a.y,1e-12,"paddle reaction torque about pivot");near(rotary.wall.power_to_particles_w,-dot(rotary.wall.reaction_torque_nm,hit.omega_rad_s),1e-12,"rotary power equals opposite reaction torque dot omega");
 material.rolling={2000,3,.1};sphere.angular_velocity_rad_s={0,1,0};sphere.velocity_m_s={.499,0,0};hit.velocity_m_s={};hit.omega_rad_s={0,1,0};h={};auto corotate=evaluate_moving_wall(sphere,hit,material,h,1e-6);near(corotate.particle.force_a.x,0,1e-12,"co-rotation zero slip at common contact point");near(corotate.particle.torque_a.y,0,1e-12,"rolling uses relative angular velocity");
