 // A stationary prescribed mesh is identical to static mesh integration.
 ParticleSystem staticworld,movingworld;staticworld.model=movingworld.model=model();staticworld.meshes={mesh};movingworld.moving_meshes={fixed};staticworld.particles=movingworld.particles={particle({0,0,.499})};for(int i=0;i<1000;++i){staticworld.step(1e-5);movingworld.step(1e-5);}near(staticworld.particles[0].position_m.z,movingworld.particles[0].position_m.z,0,"zero motion trajectory exact");near(movingworld.moving_wall_work_j,0,0,"stationary wall no work");
 double errors[3]={};for(int k=0;k<3;++k){int count=400*(1<<k);double dt=pi/(200*count);ParticleSystem world;world.model=model();world.gravity_m_s2={};PrescribedMotion up;up.linear_velocity_m_s.z=.1;world.moving_meshes.emplace_back(mesh,up);world.particles={particle({0,0,.499})};double initial=.005;for(int i=0;i<count;++i)world.step(dt);double delta=.5-(world.particles[0].position_m.z-.1*world.physical_time_s);double energy=.5*dot(world.particles[0].velocity_m_s,world.particles[0].velocity_m_s)+.5*10000*delta*delta;errors[k]=std::abs((energy-initial)-world.moving_wall_work_j);check(std::abs(world.moving_wall_work_j-.02)<1e-4,"moving normal wall analytic work");}
