 auto clump=clump_demo();clump.bodies.resize(1);clump.bodies[0].position_m={.1,.025,.04};clump.gravity_m_s2={};clump.boxes.clear();FixedBox paddle;paddle.id=2;paddle.centre_m={0,0,.04};paddle.half_m={.18,.01,.03};PrescribedMotion rpm;rpm.pivot_m={0,0,.04};rpm.rpm=30;clump.moving_meshes.emplace_back(StaticTriangleMesh(triangulated_box(paddle)),rpm);double mass=clump_properties(clump.bodies[0].pebbles,clump.bodies[0].density_kg_m3).mass_kg;auto before=clump.bodies[0].velocity_m_s;auto report=clump.step(1e-6);check(report.wall_contacts>0&&clump.moving_wall_work_j>0,"paddle drives rigid clump");near((clump.bodies[0].velocity_m_s.y-before.y)*mass,-report.moving_wall_loads[0].reaction_force_n.y*1e-6,1e-12,"clump impulse balances wall reaction");check(clump.bodies[0].velocity_m_s.y>0,"positive RPM pushes expected direction");
