 std::cout<<"PASS prescribed wall poses, relative slip/rolling, reaction torque, work balance, zero-motion equivalence and atomic guards\nwork_energy_error_J="<<errors[0]<<','<<errors[1]<<','<<errors[2]<<"\nclump_wall_work_J="<<clump.moving_wall_work_j<<'\n';return 0;
